// US-09: parse inbound Telegram update (recipe photo ingestion).
// Named functions are extracted and unit-tested outside n8n; the data
// assembly below is guarded so the file can be loaded standalone.

function isAuthorized(headers, secret) {
  if (!secret) return false;
  const source = headers || {};
  let value;
  for (const key of Object.keys(source)) {
    if (String(key).toLowerCase() === 'x-telegram-bot-api-secret-token') {
      value = source[key];
      break;
    }
  }
  if (value === undefined || value === null) return false;
  const provided = Array.isArray(value) ? value[0] : value;
  return String(provided) === String(secret);
}

function extractCode(text) {
  if (typeof text !== 'string') return '';
  const match = text.match(/FAR-\d{4}/i);
  return match ? match[0].toUpperCase() : '';
}

function selectPhotoFileId(photo) {
  if (!Array.isArray(photo) || photo.length === 0) return null;
  const last = photo[photo.length - 1];
  if (!last || typeof last.file_id !== 'string') return null;
  return last.file_id;
}

function parseUpdate(update, headers, secret) {
  if (!isAuthorized(headers, secret)) return [];
  if (!update || typeof update !== 'object') return [];
  const message = update.message;
  if (!message || typeof message !== 'object') return [];
  const chatId = message.chat ? message.chat.id : undefined;
  if (chatId === undefined || chatId === null) return [];
  const codigo_far = extractCode(message.caption) || extractCode(message.text);
  const file_id = selectPhotoFileId(message.photo);
  return [
    {
      json: {
        chat_id: chatId,
        codigo_far: codigo_far,
        file_id: file_id,
        source: 'telegram'
      }
    }
  ];
}

if (typeof $ !== 'undefined') {
  const event = $input.first().json || {};
  return parseUpdate(
    event.body || {},
    event.headers || {},
    $env.TELEGRAM_WEBHOOK_SECRET
  );
}

// US-09: decide the single reply for the parsed Telegram recipe message.
// Named functions are extracted and unit-tested outside n8n; the n8n data
// assembly is guarded with typeof $ !== 'undefined'.

function isTitularOf(order, chatId) {
  const owner = order && order.telefono !== null && order.telefono !== undefined ? String(order.telefono) : '';
  const requester = chatId === null || chatId === undefined ? '' : String(chatId);
  return owner !== '' && owner === requester;
}

function classifyAction(input) {
  const codigo = input && input.codigo_far;
  const fileId = input && input.file_id;
  const order = input && input.order;
  const chatId = input && input.chat_id;
  if (!codigo) return 'ASK_CODE';
  // Titularidad (GitHub #19): la receta solo se asocia desde el chat que creó
  // el pedido; el mismo mensaje cubre código inexistente y chat ajeno.
  if (!order || !isTitularOf(order, chatId)) return 'NOT_FOUND';
  if (order.estado !== 'PENDIENTE_RECETA') return 'NOT_PENDING';
  if (!fileId) return 'ASK_PHOTO';
  return 'UPLOAD';
}

function buildRecipeMessage(action, codigo_far) {
  if (action === 'ASK_CODE') {
    return 'No recibí el código del pedido. Reenvía la foto con el código #FAR-XXXX en el pie de foto.';
  }
  if (action === 'ASK_PHOTO') {
    return 'Tu pedido #' + codigo_far + ' está esperando la receta. Adjunta la foto de la receta con el código en el pie de foto.';
  }
  if (action === 'NOT_FOUND') {
    return 'No encontré ese pedido. Revisa el código #FAR-XXXX; la receta se asocia solo desde el chat con el que hiciste la reserva.';
  }
  if (action === 'NOT_PENDING') {
    return 'Tu pedido #' + codigo_far + ' no está esperando receta. Consulta su estado en la farmacia.';
  }
  if (action === 'UPLOAD') {
    return 'Recibimos la receta de tu pedido #' + codigo_far + '. Un químico farmacéutico la revisará y te avisaremos por este chat.';
  }
  return '';
}

function buildDriveName(codigo, timestampMs, extension) {
  return codigo + '/receta-' + timestampMs + '.' + extension;
}

if (typeof $ !== 'undefined') {
  const parsed = $('parse_recipe_message').first().json;
  const rows = $('read_ordenes').all();
  let order = null;
  if (parsed.codigo_far) {
    for (const row of rows) {
      const value = row.json || {};
      if (String(value.codigo_far) === String(parsed.codigo_far)) {
        order = value;
        break;
      }
    }
  }
  const action = classifyAction({
    codigo_far: parsed.codigo_far,
    file_id: parsed.file_id,
    order: order,
    chat_id: parsed.chat_id
  });
  return [
    {
      json: {
        chat_id: parsed.chat_id,
        source: parsed.source || 'telegram',
        codigo_far: parsed.codigo_far,
        file_id: parsed.file_id,
        action: action,
        message: buildRecipeMessage(action, parsed.codigo_far)
      }
    }
  ];
}

// US-09: final success reply after Drive upload + sheet updates.
// Named functions are extracted and unit-tested outside n8n; the n8n data
// assembly is guarded with typeof $ !== 'undefined'.

function buildRecipeMessage(action, codigo_far) {
  if (action === 'ASK_CODE') {
    return 'No recibí el código del pedido. Reenvía la foto con el código #FAR-XXXX en el pie de foto.';
  }
  if (action === 'ASK_PHOTO') {
    return 'Tu pedido #' + codigo_far + ' está esperando la receta. Adjunta la foto de la receta con el código en el pie de foto.';
  }
  if (action === 'NOT_FOUND') {
    return 'No encontré ese pedido. Revisa el código #FAR-XXXX; la receta se asocia solo desde el chat con el que hiciste la reserva.';
  }
  if (action === 'NOT_PENDING') {
    return 'Tu pedido #' + codigo_far + ' no está esperando receta. Consulta su estado en la farmacia.';
  }
  if (action === 'UPLOAD') {
    return 'Recibimos la receta de tu pedido #' + codigo_far + '. Un químico farmacéutico la revisará y te avisaremos por este chat.';
  }
  return '';
}

if (typeof $ !== 'undefined') {
  const origin = $('build_action').first().json;
  return [
    {
      json: {
        chat_id: origin.chat_id,
        source: origin.source || 'telegram',
        message: buildRecipeMessage('UPLOAD', origin.codigo_far)
      }
    }
  ];
}

/**
 * US-09 — aviso_farmaceutico.
 *
 * Cuando la receta ya quedó en Drive y el pedido pasó a RECETA_RECIBIDA, avisa a
 * cada químico farmacéutico autorizado ($env.TELEGRAM_PHARMACIST_CHAT_IDS) para
 * que apruebe o rechace (US-20). El aviso no incluye RUT ni dirección: solo el
 * código, el medicamento, la cantidad y el enlace a la receta, que se abre
 * únicamente con una cuenta con acceso a la carpeta restringida (RNF-07).
 *
 * Salida: un ítem { chat_id, message } por farmacéutico, o [] si no hay lista.
 */
function parseIdList(list) {
  const raw = typeof list === 'string' ? list : '';
  return raw.split(',').map((s) => s.trim()).filter((s) => s.length > 0);
}

function driveLink(upload) {
  if (!upload || typeof upload !== 'object') return '';
  if (upload.webViewLink) return String(upload.webViewLink);
  if (upload.id) return 'https://drive.google.com/file/d/' + upload.id + '/view';
  return '';
}

function buildPharmacistAlerts(codigoFar, order, upload, pharmacistList) {
  const ids = parseIdList(pharmacistList);
  if (!ids.length || !codigoFar) return [];
  const codigo = String(codigoFar).toUpperCase().replace(/^#/, '');
  const detalle = order
    ? ' (' + String(order.medicamento_id || 'medicamento sin id') + ' x' + String(order.cantidad || '?') + ')'
    : '';
  const enlace = driveLink(upload);
  const message =
    'Nueva receta recibida para #' + codigo + detalle + '.' +
    (enlace ? '\nVer receta: ' + enlace : '') +
    '\nPara decidir, responda: aprobar ' + codigo + '  o  rechazar ' + codigo + ' [motivo]';
  return ids.map((id) => ({ json: { chat_id: id, message: message } }));
}

// --- ensamblaje n8n ---
if (typeof $ !== 'undefined') {
  try {
    const action = $('build_action').first().json;
    const upload = $('upload_to_drive').first().json;
    const codigo = String(action.codigo_far || '').toUpperCase().replace(/^#/, '');
    const fila = $('read_ordenes').all()
      .map((r) => (r && r.json ? r.json : r))
      .find((r) => String(r.codigo_far || '').toUpperCase().replace(/^#/, '') === codigo) || null;
    return buildPharmacistAlerts(codigo, fila, upload, $env.TELEGRAM_PHARMACIST_CHAT_IDS);
  } catch (err) {
    return [];
  }
}
